-- Data backup for public.products
-- Row count: 44


select setval(pg_get_serial_sequence('public.products', 'id'), coalesce((select max(id) from public."products"), 1), true);

select vendor_id, max(vendor_seq)::integer, now()
from public.products
where vendor_seq is not null
group by vendor_id
on conflict (vendor_id) do update set
  last_seq = excluded.last_seq,
  updated_at = excluded.updated_at;

